def compute(vars):
    current = vars["v1"]
    prior = vars["v2"]

    if prior == 0:
        return None

    change_ratio = (current - prior) / prior

    return {
        "value": change_ratio,
        "trace": {
            "current_net_revenue": current,
            "prior_net_revenue": prior,
            "change": current - prior,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
